scripts.script:
local DeepLib = loadstring(game:HttpGet("https://raw.githubusercontent.com/RainCreatorHub/Deep-Lib/refs/heads/main/init.lua"))()

local window = DeepLib:Window({
    Title = "Deep-Lib Demo",
    SubTitle = "Full Example",
    Icon = "Arrow"
})

local tab = window:Tab({
    Name = "Geral",
    Icon = "Arrow"
})

local section = tab:Section({
    Name = "Tudo de Exemplo",
    Icon = "Arrow"
})

section:Paragraph({
    Name = "Texto Expansível",
    Desc = "Este é um parágrafo longo para testar o autosize de parágrafos. ",
    Icon = "Arrow"
})

section:Button({
    Name = "Clique-me",
    Desc = "Mostra uma notificação com ícone.",
    Icon = "Arrow",
    Callback = function()
        window:Notify({
            Title = "Notificação!",
            Desc = "Notificação com ícone e autosize. ",
            Icon = "Arrow",
            Options = {{Title = "Fechar"}}
        })
    end
})

section:Toggle({
    Name = "Ativar Diálogo",
    Desc = "Mostra um diálogo ao ativar.",
    Icon = "Arrow",
    Callback = function(state)
        window:Dialog({
            Title = "Diálogo",
            Desc = "Toggle está " .. (state and "Ligado" or "Desligado"),
            Icon = "Arrow",
            Options = {{Title = "OK"}}
        }):Show()
    end
})

--[[
local D = section:Dropdown({
    Name = "Escolha algo",
    Desc = "Dropdown multi-uso",
    Icon = "Arrow",
    Options = {"Opção 1", "Opção 2", "Opção 3"},
    Defalth = "Opção 1",
    Multi = false,
    Callback = function(opt) print("Selecionado:", opt) end
})

D:SetName("Selecione algo novo")
D:SetDesc("Descrição atualizada!")
D:SetIcon("Arrow")
D:SetOptions({"A", "B", "C"})
D:Refresh()
D:SetDefalth("B")
D:SetMulti(true)
]]
window:Notify({
    Title = "Bem-vindo!",
    Desc = "Test!",
    Icon = "Arrow",
    Options = {
        {Title = "Ok", Callback = function() print("Ok!") end}
    }
})

window:Dialog({
    Title = "Diálogo Inicial",
    Desc = "Esse é um diálogo de exemplo.",
    Icon = "Arrow",
    Options = {{Title = "Fechar"}}
}):Show()

